/**
 * @file      Classifier.cpp
 * @author    Guilherme Frick (frickoliveira.ee@gmail.com)
 * @brief     The two inference engines: the C99 generated by TL2cgen, and the compact table
 *            evaluator that serves as its oracle.
 * @version   1.0
 * @date      2026-11-01
 * @copyright Copyright (c) 2026
 *
 * @details   The ABI of the generated code is NOT assumed here. It was read off a @c header.h
 *            produced by running TL2cgen on a probe model of the same shape as the adopted one;
 *            see @c experiments/bench-inference/make_probe.sh. That mattered: the entry union has
 *            THREE members, not the two an educated guess would write.
 *
 *            @code
 *            union Entry { int missing; float fvalue; int qvalue; };
 *            void predict(union Entry *data, int pred_margin, float *result);
 *            int32_t get_num_feature(void);
 *            void get_num_class(int32_t *out);     // writes through a pointer, returns nothing
 *            @endcode
 *
 *            Two of those would have been got wrong by guessing, and NEITHER would have failed to
 *            compile: a two-member union has the same size and alignment, and @c get_num_class
 *            looks like it should return its answer.
 *
 * @details   Layout of the compact table artefact, which @c experiments/bench-inference/
 *            @c export_tables.py writes, little-endian:
 *            @code
 *            int32  n_trees, n_class, n_nodes, n_feat
 *            float  base[n_class]          initial margin per class
 *            int32  tree_root[n_trees]     index of each tree's root node
 *            node   nodes[n_nodes]         { float thr; int32 feat; int32 left; int32 right; }
 *            @endcode
 *            A node is a leaf when @c feat is negative, and then @c thr carries the leaf value.
 *            The margin of class @c t%n_class receives the leaf of tree @c t, which is how XGBoost
 *            interleaves the trees of a multi-class model.
 *
 * @details   The initial margin is a VECTOR per class, not a scalar, in the adopted model. That
 *            matters because a scalar would cancel in the softmax and a vector does not. It was
 *            the cross check between these two engines that surfaced it.
 */
#include "src/ids_sensor/Classifier.hpp"

#include <cerrno>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <vector>

/* ------------------------------------------------------------------ ABI gerada */
extern "C"
{
/**
 * @brief One feature value, as the generated code expects it.
 * @details Declared here rather than by including the generated @c header.h, so that this file
 *          compiles whether or not the TL2cgen step ran. The definition is copied VERBATIM from a
 *          generated header, @c qvalue included: a union that merely has the right size would be
 *          layout-compatible by accident, and relying on accident is what this comment exists to
 *          prevent.
 */
union Entry
{
    int   missing; ///< Negative marks the value as absent.
    float fvalue;  ///< The value itself, when present.
    int   qvalue;  ///< Quantised form, used by the generated code in quantised mode.
};

/* Weak symbols: when the TL2cgen step did not run, these resolve to null instead of failing the
 * link, and ::ids::Tl2cgenClassifier::Create() reports ModelNotAvailable. The attribute is a
 * compiler extension, which AUTOSAR would rather avoid; the alternative is a conditional
 * compilation macro, and rule A16-0-1 restricts the pre-processor to include guards and file
 * inclusion. Of the two deviations this is the one that keeps the decision visible in code that
 * the compiler checks. */
__attribute__((weak)) void predict(union Entry *data, int pred_margin, float *result);
__attribute__((weak)) std::int32_t get_num_feature(void);
__attribute__((weak)) void get_num_class(std::int32_t *out);
}

namespace ids
{

namespace
{

/**
 * @brief One node of the compact table.
 */
struct Node
{
    float        thr;   ///< Split threshold, or the leaf value when this is a leaf.
    std::int32_t feat;  ///< Feature index, or negative when this is a leaf.
    std::int32_t left;  ///< Child taken when the value is BELOW the threshold.
    std::int32_t right; ///< Child taken otherwise.
};

constexpr std::size_t kNodeBytes = 16U; ///< Size of one node in the artefact.
constexpr std::size_t kHeaderInts = 4U; ///< int32 fields of the artefact header.

/// Upper bound on how deep a traversal may go. The adopted model has depth eight, so this is
/// headroom; it exists because a CORRUPTED table could describe a cycle, and a tree walk with no
/// bound would then never return. A bounded walk also gives the engine a worst case execution time
/// by construction, which is the property that makes it defensible on an ECU.
constexpr int kDepthGuard = 64;

/**
 * @brief Turn margins into probabilities.
 * @param[in] margins Per-class margins.
 * @return Per-class probabilities summing to one.
 * @details In @c float, and with the maximum subtracted first, which is what XGBoost's own softmax
 *          does. Computing in double and casting afterwards would be more accurate and LESS equal
 *          to the reference, and equality is what is wanted here.
 */
ProbVec Softmax(const ProbVec &margins)
{
    ProbVec out = ProbVec();

    float maior = margins[0];
    for (std::size_t i = 1U; i < kNumClasses; ++i)
    {
        if (margins[i] > maior)
        {
            maior = margins[i];
        }
    }

    float soma = 0.0F;
    for (std::size_t i = 0U; i < kNumClasses; ++i)
    {
        out[i] = std::exp(margins[i] - maior);
        soma += out[i];
    }

    for (std::size_t i = 0U; i < kNumClasses; ++i)
    {
        out[i] /= soma;
    }
    return out;
}

} // namespace

TrafficClass ArgMax(const ProbVec &probabilities)
{
    std::size_t melhor = 0U;
    for (std::size_t i = 1U; i < kNumClasses; ++i)
    {
        /* Strictly greater, so a tie keeps the FIRST class. numpy.argmax does the
         * same, and the reported metrics were computed with it. */
        if (probabilities[i] > probabilities[melhor])
        {
            melhor = i;
        }
    }
    return static_cast<TrafficClass>(melhor);
}

/* --------------------------------------------------------------- TL2cgen */

ara::core::Result<std::unique_ptr<Tl2cgenClassifier>> Tl2cgenClassifier::Create()
{
    using Res = ara::core::Result<std::unique_ptr<Tl2cgenClassifier>>;

    /* The weak symbols are null when the TL2cgen step did not run. This is the one
     * place in the sensor where "the build is incomplete" is a runtime answer rather
     * than a link error, and it is why IdsSensorErrc::ModelNotAvailable exists. */
    if ((predict == nullptr) || (get_num_feature == nullptr) || (get_num_class == nullptr))
    {
        return Res::FromError(ara::core::ErrorCode(IdsSensorErrc::ModelNotAvailable));
    }
    else
    {
        /* A generated model is linked in. */
    }

    /* Its SHAPE is checked, not trusted. A model generated for a different feature
     * count would make the generated code read past the entry array, and a different
     * class count would make it write past the probability vector. Both are silent. */
    if (get_num_feature() != static_cast<std::int32_t>(kNumFeatures))
    {
        return Res::FromError(ara::core::ErrorCode(IdsSensorErrc::InvalidConfiguration));
    }
    else
    {
        /* Sixteen features, as this build expects. */
    }

    std::int32_t classes = 0;
    get_num_class(&classes);
    if (classes != static_cast<std::int32_t>(kNumClasses))
    {
        return Res::FromError(ara::core::ErrorCode(IdsSensorErrc::InvalidConfiguration));
    }
    else
    {
        /* Five classes, as this build expects. */
    }

    return Res::FromValue(std::unique_ptr<Tl2cgenClassifier>(new Tl2cgenClassifier()));
}

Tl2cgenClassifier::Tl2cgenClassifier() noexcept
{
}

ProbVec Tl2cgenClassifier::Predict(const FeatureVec &x) const
{
    union Entry entradas[kNumFeatures];
    for (std::size_t i = 0U; i < kNumFeatures; ++i)
    {
        /* Writing fvalue leaves `missing` holding that float's bit pattern, which is
         * not the negative marker unless the value is a NaN. So a present value needs
         * no further marking, and a NaN feature would be treated as absent. The data
         * has no NaN; see the warning on CompactClassifier about the missing
         * direction, which is the same gap seen from the other engine. */
        entradas[i].fvalue = x[i];
    }

    ProbVec out = ProbVec();
    /* The generated predict() ACCUMULATES into the result with +=, so the buffer has
     * to start at zero. ProbVec() value-initialises, which is what does it; dropping
     * those parentheses would make every prediction depend on the stack's leftovers. */
    predict(entradas, 0, out.data());
    /* pred_margin = 0 makes predict() apply its own postprocess, which for
     * multi:softprob is the softmax. So no Softmax() call here: applying it twice
     * would flatten the distribution and still look plausible. */
    return out;
}

/* --------------------------------------------------------------- compacto */

/**
 * @brief Node tables of the compact engine.
 */
struct CompactClassifier::Impl
{
    std::int32_t              nTrees = 0; ///< Number of trees in the model.
    std::vector<float>        base;       ///< Initial margin per class.
    std::vector<std::int32_t> roots;      ///< Root node index of each tree.
    std::vector<Node>         nodes;      ///< All nodes of all trees.
};

ara::core::Result<std::unique_ptr<CompactClassifier>> CompactClassifier::Create(const std::string &tablesPath)
{
    using Res = ara::core::Result<std::unique_ptr<CompactClassifier>>;

    errno                 = 0;
    std::FILE *const file = std::fopen(tablesPath.c_str(), "rb");
    if (file == nullptr)
    {
        if (errno == ENOENT)
        {
            return Res::FromError(ara::core::ErrorCode(IdsSensorErrc::ArtefactNotFound));
        }
        return Res::FromError(ara::core::ErrorCode(IdsSensorErrc::ArtefactUnreadable, errno));
    }
    else
    {
        /* File opened. */
    }

    std::int32_t cabecalho[kHeaderInts] = {0, 0, 0, 0};
    if (std::fread(cabecalho, sizeof(std::int32_t), kHeaderInts, file) != kHeaderInts)
    {
        static_cast<void>(std::fclose(file));
        return Res::FromError(ara::core::ErrorCode(IdsSensorErrc::ArtefactCorrupted));
    }

    const std::int32_t nTrees = cabecalho[0];
    const std::int32_t nClass = cabecalho[1];
    const std::int32_t nNodes = cabecalho[2];
    const std::int32_t nFeat  = cabecalho[3];

    /* Every count is checked before anything is sized from it. A negative or absurd
     * count in a truncated file would otherwise become a huge allocation or a
     * negative size cast to an enormous unsigned one. */
    const bool contagensOk = ((nTrees > 0) && (nNodes > 0) && (nClass == static_cast<std::int32_t>(kNumClasses)) &&
                              (nFeat == static_cast<std::int32_t>(kNumFeatures)));
    if (!contagensOk)
    {
        static_cast<void>(std::fclose(file));
        return Res::FromError(ara::core::ErrorCode(IdsSensorErrc::ArtefactCorrupted));
    }

    std::unique_ptr<Impl> impl(new Impl());
    impl->nTrees = nTrees;
    impl->base.resize(static_cast<std::size_t>(nClass));
    impl->roots.resize(static_cast<std::size_t>(nTrees));
    impl->nodes.resize(static_cast<std::size_t>(nNodes));

    const bool lidoOk =
        ((std::fread(impl->base.data(), sizeof(float), impl->base.size(), file) == impl->base.size()) &&
         (std::fread(impl->roots.data(), sizeof(std::int32_t), impl->roots.size(), file) == impl->roots.size()) &&
         (std::fread(impl->nodes.data(), kNodeBytes, impl->nodes.size(), file) == impl->nodes.size()));
    static_cast<void>(std::fclose(file));
    if (!lidoOk)
    {
        return Res::FromError(ara::core::ErrorCode(IdsSensorErrc::ArtefactCorrupted));
    }

    /* Every index the traversal will follow is validated HERE, once, so that
     * Predict() needs no bounds check on the hot path. A root or a child pointing
     * outside the node array is the difference between a wrong answer and a read out
     * of bounds. */
    bool indicesOk = true;
    for (std::size_t t = 0U; (t < impl->roots.size()) && indicesOk; ++t)
    {
        indicesOk = ((impl->roots[t] >= 0) && (static_cast<std::size_t>(impl->roots[t]) < impl->nodes.size()));
    }
    for (std::size_t i = 0U; (i < impl->nodes.size()) && indicesOk; ++i)
    {
        const Node &n = impl->nodes[i];
        if (n.feat < 0)
        {
            /* A leaf: thr carries its value and the children are unused. */
            continue;
        }
        indicesOk = ((n.feat < static_cast<std::int32_t>(kNumFeatures)) && (n.left >= 0) && (n.right >= 0) &&
                     (static_cast<std::size_t>(n.left) < impl->nodes.size()) &&
                     (static_cast<std::size_t>(n.right) < impl->nodes.size()));
    }
    if (!indicesOk)
    {
        return Res::FromError(ara::core::ErrorCode(IdsSensorErrc::ArtefactCorrupted));
    }

    return Res::FromValue(std::unique_ptr<CompactClassifier>(new CompactClassifier(std::move(impl))));
}

CompactClassifier::CompactClassifier(std::unique_ptr<Impl> impl) noexcept : m_impl(std::move(impl))
{
}

CompactClassifier::~CompactClassifier() = default;

ProbVec CompactClassifier::Predict(const FeatureVec &x) const
{
    const Impl &impl = *m_impl;

    ProbVec margens = ProbVec();
    for (std::size_t c = 0U; c < kNumClasses; ++c)
    {
        margens[c] = impl.base[c];
    }

    for (std::int32_t t = 0; t < impl.nTrees; ++t)
    {
        std::int32_t i = impl.roots[static_cast<std::size_t>(t)];
        for (int profundidade = 0; profundidade < kDepthGuard; ++profundidade)
        {
            const Node &n = impl.nodes[static_cast<std::size_t>(i)];
            if (n.feat < 0)
            {
                break;
            }
            /* STRICTLY below goes left, which is the "yes" branch of XGBoost. The
             * exporter already resolved yes/no into left/right, so this comparison
             * must not be flipped to <= : a value exactly on a threshold would then
             * take the other branch, and thresholds sit on observed values. */
            i = (x[static_cast<std::size_t>(n.feat)] < n.thr) ? n.left : n.right;
        }
        /* Tree t contributes to class t % n_class: that is how XGBoost interleaves
         * the trees of a multi-class model, one round producing one tree per class. */
        margens[static_cast<std::size_t>(t) % kNumClasses] += impl.nodes[static_cast<std::size_t>(i)].thr;
    }

    return Softmax(margens);
}

} // namespace ids
